const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    since: oneWeekAgo.toISOString(),
    until: now.toISOString(),
    owner: $env.GITHUB_REPO_OWNER || '{{ $parameter["repoOwner"] }}',
    repo: $env.GITHUB_REPO_NAME || '{{ $parameter["repoName"] }}',
    token: $env.GITHUB_TOKEN || '{{ $parameter["githubToken"] }}'
  }
}];

const commits = items[0].json || [];
const issues = items[1].json || [];
const prs = items[2].json || [];

// Filter PRs to only merged ones from the past week
const mergedPRs = prs.filter(pr => pr.merged_at && new Date(pr.merged_at) >= new Date($json.since) && new Date(pr.merged_at) <= new Date($json.until));

// Filter issues to only closed ones (excluding PRs which are also issues in GitHub API)
const closedIssues = issues.filter(issue => !issue.pull_request && issue.closed_at && new Date(issue.closed_at) >= new Date($json.since) && new Date(issue.closed_at) <= new Date($json.until));

// Format commits
const formattedCommits = commits.map(c => ({
  sha: c.sha.substring(0, 7),
  message: c.commit.message.split('\n')[0],
  author: c.commit.author.name,
  date: c.commit.author.date,
  url: c.html_url
}));

// Format issues
const formattedIssues = closedIssues.map(i => ({
  number: i.number,
  title: i.title,
  author: i.user.login,
  closed_at: i.closed_at,
  labels: i.labels.map(l => l.name),
  url: i.html_url
}));

// Format PRs
const formattedPRs = mergedPRs.map(p => ({
  number: p.number,
  title: p.title,
  author: p.user.login,
  merged_at: p.merged_at,
  labels: p.labels.map(l => l.name),
  url: p.html_url
}));

return [{
  json: {
    period: {
      since: $json.since,
      until: $json.until
    },
    repo: {
      owner: $json.owner,
      name: $json.repo
    },
    stats: {
      commits: formattedCommits.length,
      closedIssues: formattedIssues.length,
      mergedPRs: formattedPRs.length
    },
    commits: formattedCommits,
    closedIssues: formattedIssues,
    mergedPRs: formattedPRs
  }
}];

const data = items[0].json;
const language = $env.SUMMARY_LANGUAGE || '{{ $parameter["language"] }}' || 'EN';

const langPrompts = {
  EN: `You are a senior software engineer writing a weekly development summary for stakeholders.

Generate a concise, narrative weekly summary in ENGLISH based on the following GitHub activity data:

Repository: ${data.repo.owner}/${data.repo.name}
Period: ${new Date(data.period.since).toLocaleDateString()} to ${new Date(data.period.until).toLocaleDateString()}

Statistics:
- Commits: ${data.stats.commits}
- Closed Issues: ${data.stats.closedIssues}
- Merged PRs: ${data.stats.mergedPRs}

Commits:
${data.commits.map(c => `- [${c.sha}] ${c.message} (by ${c.author} on ${new Date(c.date).toLocaleDateString()})`).join('\n') || 'None'}

Closed Issues:
${data.closedIssues.map(i => `- #${i.number}: ${i.title} (by ${i.author}, labels: ${i.labels.join(', ') || 'none'})`).join('\n') || 'None'}

Merged Pull Requests:
${data.mergedPRs.map(p => `- #${p.number}: ${p.title} (by ${p.author}, labels: ${p.labels.join(', ') || 'none'})`).join('\n') || 'None'}

Write a professional, narrative summary (2-3 paragraphs) highlighting key achievements, trends, and notable work. Focus on what was accomplished, not just a list. Use a tone suitable for both technical and non-technical stakeholders.`,
  FR: `Vous êtes un ingénieur logiciel senior rédigeant un résumé hebdomadaire de développement pour les parties prenantes.

Générez un résumé narratif hebdomadaire concis en FRANÇAIS basé sur les données d'activité GitHub suivantes :

Dépôt : ${data.repo.owner}/${data.repo.name}
Période : ${new Date(data.period.since).toLocaleDateString('fr-FR')} au ${new Date(data.period.until).toLocaleDateString('fr-FR')}

Statistiques :
- Commits : ${data.stats.commits}
- Problèmes fermés : ${data.stats.closedIssues}
- PR fusionnées : ${data.stats.mergedPRs}

Commits :
${data.commits.map(c => `- [${c.sha}] ${c.message} (par ${c.author} le ${new Date(c.date).toLocaleDateString('fr-FR')})`).join('\n') || 'Aucun'}

Problèmes fermés :
${data.closedIssues.map(i => `- #${i.number}: ${i.title} (par ${i.author}, étiquettes: ${i.labels.join(', ') || 'aucune'})`).join('\n') || 'Aucun'}

Pull Requests fusionnées :
${data.mergedPRs.map(p => `- #${p.number}: ${p.title} (par ${p.author}, étiquettes: ${p.labels.join(', ') || 'aucune'})`).join('\n') || 'Aucun'}

Rédigez un résumé narratif professionnel (2-3 paragraphes) mettant en évidence les principales réalisations, tendances et travaux notables. Concentrez-vous sur ce qui a été accompli, pas seulement une liste. Utilisez un ton adapté aux parties prenantes techniques et non-techniques.`
};

return [{
  json: {
    ...data,
    prompt: langPrompts[language] || langPrompts.EN,
    language
  }
}];

const response = items[0].json;
const summary = response.content?.[0]?.text || 'Failed to generate summary';
const data = $json;

const language = data.language || 'EN';
const periodStart = new Date(data.period.since).toLocaleDateString(language === 'FR' ? 'fr-FR' : 'en-US');
const periodEnd = new Date(data.period.until).toLocaleDateString(language === 'FR' ? 'fr-FR' : 'en-US');

const title = language === 'FR' 
  ? `📊 Résumé Hebdomadaire de Développement - ${data.repo.owner}/${data.repo.name} (${periodStart} - ${periodEnd})`
  : `📊 Weekly Dev Summary - ${data.repo.owner}/${data.repo.name} (${periodStart} - ${periodEnd})`;

const statsHeader = language === 'FR' 
  ? '**Statistiques de la semaine**'
  : '**This Week\'s Statistics**';
const commitsLabel = language === 'FR' ? 'Commits' : 'Commits';
const issuesLabel = language === 'FR' ? 'Problèmes fermés' : 'Closed Issues';
const prsLabel = language === 'FR' ? 'PR fusionnées' : 'Merged PRs';

const formattedMessage = `${title}

${statsHeader}
- ${commitsLabel}: ${data.stats.commits}
- ${issuesLabel}: ${data.stats.closedIssues}
- ${prsLabel}: ${data.stats.mergedPRs}

---

${summary}

---
*Generated automatically via n8n + Claude API*`;

return [{
  json: {
    ...data,
    summary,
    formattedMessage,
    title
  }
}];
